pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    keepMyEther c;
    function setUp() public { c = new keepMyEther(); }
    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(c));
        amount = bound(amount, 1, 1 ether);
        vm.deal(actor, amount);
        vm.startPrank(actor);
        (bool depOk, ) = address(c).call{value: amount}("");
        assertTrue(depOk);
        c.withdraw();
        vm.stopPrank();
        assertTrue(c.balances(actor) == 0);
    }
}
